fn prime_num(n: u64) -> bool {
    // Because input >= 2, we can safely start from 2
    // Calculate integer square root of n to reduce checks
    let limit = (n as f64).sqrt() as u64;

    for k in 2..=limit {
        if n % k == 0 {
            return false; // divisor found, not prime
        }
    }

    true // no divisors found, n is prime
}